/**
 * Chosen thaw method when fromFrozen is true. "fridge" is slow and safest; "cold_water" is faster but requires more attention. Used to tailor PitMaster's thaw and surface-dry guidance.
 * @nullable
 */
export type AiPredictBodyThawMethod =
  | (typeof AiPredictBodyThawMethod)[keyof typeof AiPredictBodyThawMethod]
  | null;

export const AiPredictBodyThawMethod = {
  fridge: "fridge",
  cold_water: "cold_water",
  microwave: "microwave",
  counter: "counter",
  cook_from_frozen: "cook_from_frozen",
} as const;

/**
 * Deterministic cook schedule anchors computed from heuristic rules (calcSchedule). Sent alongside the AI predict request so PitMaster can focus on personalising rather than re-deriving the full timeline.
 */
export interface BaselineSchedule {
  /** When to light/start the grill (before meat goes on) */
  preheatStartAt: string;
  /** When to put the meat on the grill */
  meatOnAt: string;
  /**
   * Estimated wrap time (null if the cut does not stall)
   * @nullable
   */
  wrapAt?: string | null;
  /**
   * Estimated internal temp at wrap (null if no wrap)
   * @nullable
   */
  wrapTempF?: number | null;
  /** When to pull the meat off the grill */
  pullAt: string;
  /** End of rest period / serve time */
  restEndAt: string;
  /** Active cook time in minutes (meat-on to pull) */
  cookMins: number;
  /** Preheat time in minutes */
  preheatMins: number;
  /** Rest time in minutes */
  restMins: number;
}

export interface AiPredictBody {
  /** @nullable */
  grillId?: number | null;
  foodType: string;
  /** @nullable */
  weightLbs?: number | null;
  /** @nullable */
  cookTempF?: number | null;
  /** @nullable */
  targetTempF?: number | null;
  /** @nullable */
  desiredFinishAt?: string | null;
  /**
   * Minutes needed to start and bring the grill up to cook temperature
   * @nullable
   */
  preheatMinutes?: number | null;
  /**
   * Outdoor ambient temperature in Fahrenheit, used to adjust cook time estimates. May be either current conditions or a forecast for the cook day (see outdoorTempIsForecast).
   * @nullable
   */
  outdoorTempF?: number | null;
  /**
   * True when outdoorTempF is a forecasted value for the cook day (Pro). False or omitted when it is the current ambient temperature.
   * @nullable
   */
  outdoorTempIsForecast?: boolean | null;
  /**
   * True when the meat is starting from a fully frozen state and needs to be thawed before cooking. PitMaster will factor in thaw timing, surface drying, and dry-brine adjustments.
   * @nullable
   */
  fromFrozen?: boolean | null;
  /**
   * Chosen thaw method when fromFrozen is true. "fridge" is slow and safest; "cold_water" is faster but requires more attention. Used to tailor PitMaster's thaw and surface-dry guidance.
   * @nullable
   */
  thawMethod?: AiPredictBodyThawMethod;
  /**
   * Cooking technique chosen by the user (e.g. "Low & Slow", "Hot & Fast", "Rotisserie", "Reverse Sear"). Influences time estimate and wrap guidance.
   * @nullable
   */
  cookingMethod?: string | null;
  /**
   * Whether the meat is injected ("Injected" or "Not Injected"). Injected cuts retain more moisture and experience a shorter stall.
   * @nullable
   */
  injection?: string | null;
  /**
   * How often the user plans to spritz/mop the meat during the cook (e.g. "No Spritz", "Every 30 min", "Every Hour", "Once at Stall"). Affects bark development and moisture retention.
   * @nullable
   */
  spritzFrequency?: string | null;
  /**
   * User's intended wrap or finish method (e.g. "No Wrap", "Butcher Paper at Stall", "Foil at Stall (Texas Crutch)", "Foil Boat"). PitMaster should align wrap recommendation with this preference.
   * @nullable
   */
  wrapFinish?: string | null;
  /**
   * Starting temperature state of the meat ("Cold from Fridge" or "Tempered to Room Temp"). Cold-from-fridge meat adds ~20–30 min to large cuts; tempered meat cooks at baseline pace.
   * @nullable
   */
  meatStartTemp?: string | null;
  /**
   * Optional free-text cook notes from the user (e.g. wood choice, rub details, special instructions). PitMaster factors these into timing, technique, and tip recommendations.
   * @nullable
   */
  notes?: string | null;
  /**
   * Number of individual pieces or racks being cooked. Used to compute grill load density when the grill's cooking surface area is known.
   * @nullable
   */
  pieceCount?: number | null;
  /**
   * True when each piece cooks independently and additional pieces do not extend cook time (e.g. steaks, chops, sausage). False for large single-mass cuts where total weight drives cook time.
   * @nullable
   */
  isIndividualCook?: boolean | null;
  /**
   * Human-readable size description chosen by the user (e.g. "6 thighs · ≈ 2.4 lbs est." or "2 racks · ≈ 4.5 lbs est."). Included in the prompt when provided.
   * @nullable
   */
  sizingLabel?: string | null;
  /**
   * Name of the preset style the user selected (e.g. "3-2-1 Method", "Texas Style (No Wrap)"). Mentioned in the prompt for context; the individual technique fields above already reflect its settings.
   * @nullable
   */
  cookingStylePreset?: string | null;
  /**
   * ID of an existing cook record. When present, the server patches the cook with AI refinement results (wrap times, check-in schedule, sequenceData) after responding.
   * @nullable
   */
  cookId?: number | null;
  /** Deterministic schedule anchors computed by calcSchedule on the client before the AI call. Sent as context so PitMaster personalises rather than re-derives the full timeline from scratch. */
  baselineSchedule?: BaselineSchedule | null;
}

