export interface AiPredictResponse {
  /** Active cook time only (food on → off grill), excluding preheat and rest */
  estimatedDurationMinutes: number;
  /** Minutes needed to start and bring the grill up to cook temperature */
  preheatMinutes: number;
  /**
   * When to light/start the grill, accounting for preheat time
   * @nullable
   */
  grillLightAt: string | null;
  /**
   * When to put food on the grill
   * @nullable
   */
  suggestedStartAt: string | null;
  /**
   * When food comes off the grill (before rest)
   * @nullable
   */
  estimatedFinishAt: string | null;
  /**
   * When food is ready to serve (after rest)
   * @nullable
   */
  serveAt: string | null;
  wrap: WrapRecommendation;
  confidence: AiPredictResponseConfidence;
  rationale: string;
  tips: string[];
  /** AI-generated check-in schedule tailored to this specific meat, technique, and cook plan. Each item fires at offsetMinutes after meatOnAt. */
  checkins: AiCheckinItem[];
  /** True when the per-grill fingerprint adjusted the time estimate or note */
  fingerprintApplied: boolean;
  /**
   * Human-readable note about how the grill's fingerprint was applied
   * @nullable
   */
  fingerprintNote: string | null;
  /**
   * Source of the fingerprint adjustment (per-grill learned pace, user-wide fallback, or pit bias only)
   * @nullable
   */
  fingerprintSource: AiPredictResponseFingerprintSource;
  /**
   * When fromFrozen is true and the user's desiredFinishAt is too soon for a full thaw, PitMaster may suggest a later serve time that allows for proper thawing. Null when not applicable.
   * @nullable
   */
  recommendedServeAt?: string | null;
  /**
   * Human-readable explanation for the recommendedServeAt adjustment (e.g., why thawing requires more lead time).
   * @nullable
   */
  recommendedServeReason?: string | null;
  /** Ordered list of time-contribution factors explaining what drives the cook time estimate. Present when enough context exists to build a meaningful breakdown; absent for minimal-input requests. The first item is always the base cook time; subsequent items are identified add-ons (stall, grill load, cold weather, learned pace, thaw+temper). */
  factorBreakdown?: FactorBreakdownItem[];
  /** True when the AI prediction call timed out and a fallback estimate was used instead of a live AI response. */
  timedOut?: boolean;
}

